// names are shown as endonyms regardless of the active UI language. Amharic
// addresses the user with the feminine singular ("ሽ" / "-ኢ" forms) because AWA
// is for women. Amharic has no plural distinction after a number, so the
// `_one`/`_other` keys carry the same form where the noun does not change.
// NATIVE REVIEW REQUIRED before publication.
