          hiddenInfoDescription: 'አጋርህ ከአንተ ጋር የምታጋራውን ትመርጣለች። እነዚህን ምርጫዎች በማንኛውም ጊዜ መቀየር ትችላለች።',
          hiddenInfoParagraph1: 'አጋርህ ከአንተ ጋር ማጋራት በምትፈልገው መረጃ ላይ ቁጥጥር አላት።',
          hiddenInfoParagraph2: 'መረጃ በቦታህ ላይ ካልታየ፣ እሷ ለማጋራት አልመረጠችም ማለት ብቻ ሊሆን ይችላል።',
          hiddenInfoParagraph3: 'ምርጫዎቿ በማንኛውም ጊዜ ሊለወጡ ይችላሉ። AWA በጋራ አሁን መዳረሻ ያለህባቸውን መረጃዎች ብቻ ያሳይሃል።',
          understandingTitle: 'የተጋራውን መረጃ መረዳት',
          understandingDescription: 'ስለ ዑደት ቀን፣ አሁን ያለ ደረጃ፣ ለም ጊዜ፣ የተገመተ እንቁላል መልቀቅ እና የሚቀጥለው የወር አበባ ቀላል ማብራሪያዎች።',
          understandingIntro: 'ከአንተ ጋር የተጋራው መረጃ ምን ሊያመለክት እንደሚችል እነሆ፦',
          termCycleDay: 'የዑደት ቀን',
          descriptionCycleDay: 'የመጨረሻ የወር አበባዋ ከጀመረ ወዲህ ያለፉትን ቀናት ብዛት ያመለክታል።',
          termCurrentPhase: 'የአሁኑ ደረጃ',
          descriptionCurrentPhase: 'ሲገኝ የዑደቱን የአሁኑ ደረጃ ያመለክታል።',
